VALUES ('sbu_tech_kb_v1_p2_c014', '| Stage | What happens |', 2, '| Stage | What happens |
| --- | --- |
| 1. Discovery & Planning | Understand the client''s goals, users, requirements, constraints and success criteria. Define scope and milestones. |
| 2. Strategy & Architecture | Plan system architecture, database models, API contracts, integrations, security and infrastructure. |
| 3. Design & Development | Create user experiences and build modular software in iterative engineering sprints. |
| 4. Testing & Quality Assurance | Run functional, integration, performance, security and accessibility checks relevant to the project. |
| 5. Deployment & Ongoing Support | Deploy the solution, monitor production, hand over source code and documentation, and provide agreed support. |', '{"document_id": "sbu_tech_kb_v1", "source_file": "SBU_TECH.pdf", "chunk_index": 14, "content_type": "tabular_data"}'::jsonb, '[-0.003346,0.014976,0.034035,0.011616,-0.004446,-0.019047,0.018077,0.008766,-0.023808,-0.07259,0.0002,-0.006738,0.023741,-0.011553,0.004391,0.008257,0.030306,0.020811,-0.012726,-0.019281,-0.001806,-0.000247,-0.000536,0.022417,-0.012948,0.009847,0.01504,-0.043501,-0.02243,0.169328,-0.017879,-0.011414,0.008597,-0.02702,-0.004678,-0.020479,-0.034855,-0.00267,0.002662,-0.013255,-0.006242,0.025936,-0.00272,-0.000463,0.004524,0.005241,0.015009,-0.029187,0.002643,0.024808,0.00523,0.020338,0.019906,-0.037478,-0.002246,-0.005815,0.004422,0.023744,0.021831,-0.010401,-0.009581,0.007853,0.014489,0.001384,-0.010309,-0.004538,0.001188,0.006193,0.008504,-0.038864,0.031002,0.038243,-0.00527,0.023295,0.008644,-0.026676,-0.019938,0.031119,-0.007318,0.012111,0.003614,-0.027024,-0.024275,0.012092,-0.015684,0.048665,-0.004318,-0.012249,0.017606,0.01288,-0.033586,0.01689,0.011268,0.011758,-0.026964,-0.005081,0.007513,-0.047696,-0.00601,-0.002875,-0.03564,0.020725,-0.027264,0.023302,-0.015869,0.007284,-0.038178,0.024224,0.052599,-0.000686,-0.012115,-0.215207,-0.006123,-0.006491,0.01153,0.105344,0.003605,-0.023292,-0.011788,0.050953,-0.011642,0.037398,-0.014606,-0.006125,-0.02759,0.006675,0.00621,-0.01409,-0.016995,-0.015912,-0.01425,0.017257,-0.016296,-0.00434,0.009164,-0.019227,-0.0064,0.018355,0.004879,-0.002989,0.026213,0.021964,-0.007357,-0.018388,-0.0207,0.01876,-0.00895,-0.013599,-0.012711,0.000819,-0.002236,0.013073,-0.04852,0.024041,-0.012452,-0.047476,0.010234,-0.003979,0.02087,-0.019334,-0.031362,-0.001823,-0.054431,0.052561,-0.01735,0.013727,-0.007699,0.019496,-0.024129,0.035177,-0.009738,0.00307,-0.013258,-0.019758,0.011834,0.005183,-4.3e-05,0.013415,0.002213,-0.003294,0.047629,-0.020713,0.050291,-0.02791